def main(args: dict) -> dict:
    import json
    import re
    supported = ['工作请示', '工作报告', '工作通知', '会议纪要']
    aliases = {'请示': '工作请示', '报告': '工作报告', '通知': '工作通知'}
    query = args.get('query', '')
    data = {}
    for _ in range(3):
        if isinstance(query, str):
            query = query.strip().lstrip('\ufeff')
            if query.startswith('```'):
                query = re.sub(r'^```[^\n]*\n?', '', query)
                query = re.sub(r'\n?```\s*$', '', query).strip()
            try:
                decoded = json.loads(query)
            except (ValueError, TypeError):
                decoded = None
            if isinstance(decoded, dict):
                query = decoded
        if isinstance(query, dict):
            if not any(k in query for k in ['公文类型', 'doc_type', '公文原文', '公文内容', 'doc_text']) and 'query' in query:
                query = query['query']
                continue
            data = query
        elif isinstance(query, str):
            # Use the next field label as a boundary, including when both fields are on one line.
            label = r'[\"\'“”‘’]?公文(?:原文|内容)[\"\'“”‘’]?\s*(?:[:：=]|是|为)\s*'
            m = re.search(r'[\"\'“”‘’]?公文类型[\"\'“”‘’]?\s*(?:[:：=]|是|为)\s*(.*?)' +
                          r'(?=' + label + r'|[\r\n，,；;]|$)', query, re.S)
            t = re.search(label + r'([\s\S]*)', query)
            data = {'公文类型': m.group(1) if m else '', '公文原文': t.group(1) if t else ''}
        break
    if not isinstance(data, dict):
        data = {}
    kind = data.get('公文类型', data.get('doc_type', ''))
    text = data.get('公文原文', data.get('公文内容', data.get('doc_text', '')))
    if isinstance(kind, str):
        kind = re.sub(r'[\s\u200b\ufeff]', '', kind).strip('\"\'“”‘’，,；;。')
        kind = aliases.get(kind, kind)
    else:
        kind = ''
    errors = []
    if not kind:
        errors.append('未读取到公文类型，请将公文类型和公文原文一起填入测试对话输入框')
    elif kind not in supported:
        errors.append('读取到的公文类型“' + kind + '”不在预设范围，支持：' + '、'.join(supported))
    if not isinstance(text, str) or not text.strip():
        errors.append('公文原文不能为空，且必须为文本')
    text = text.strip() if isinstance(text, str) else ''
    notice = '；'.join(errors)
    error = {'公文类型': kind, '初审结论': '入参异常', '待核对要点清单': [], '审阅说明': notice}
    return {'valid': not errors, 'doc_type': kind, 'doc_text': text,
            'error_result': json.dumps(error, ensure_ascii=False) if errors else '', 'notice': notice}

