def parse_model(raw):
    import json
    import re
    if isinstance(raw, dict):
        return raw
    if not isinstance(raw, str):
        raise ValueError('模型未返回文本或对象')
    raw = re.sub(r'<think>.*?</think>', '', raw, flags=re.S).strip()
    try:
        obj = json.loads(raw)
        if isinstance(obj, dict):
            return obj
    except (ValueError, TypeError):
        pass
    match = re.search(r'```(?:json)?\s*(.*?)```', raw, re.S)
    if match:
        obj = json.loads(match.group(1))
        if isinstance(obj, dict):
            return obj
    pos = raw.find('{')
    if pos >= 0:
        obj, _ = json.JSONDecoder().raw_decode(raw[pos:])
        if isinstance(obj, dict):
            return obj
    raise ValueError('模型输出不是有效JSON对象')

def main(args: dict) -> dict:
    import json
    try:
        obj = parse_model(args.get('raw_output'))
        status = obj.get('初审状态')
        if status not in ['通过', '待核对', '需补充']:
            raise ValueError('初审状态缺失或不合法')
        conclusion = obj.get('初审结论')
        points = obj.get('待核对要点清单')
        explanation = obj.get('审阅说明')
        info = obj.get('关键要素')
        if not isinstance(conclusion, str) or not conclusion.strip():
            raise ValueError('缺少初审结论')
        if not isinstance(points, list) or any(not isinstance(x, str) or not x.strip() for x in points):
            raise ValueError('核对要点必须为非空字符串组成的数组')
        if not isinstance(explanation, str) or not explanation.strip() or not isinstance(info, dict):
            raise ValueError('缺少审阅说明或关键要素对象')
        points = list(dict.fromkeys(points))
        if status == '通过' and points:
            status = '待核对'
            conclusion = '材料基本完整，需进一步核实'
    except (ValueError, TypeError, KeyError):
        status, conclusion = '需人工复核', '模型结果格式异常，需人工复核'
        points = ['重新运行初审或人工核对原始公文']
        explanation, info = '模型未返回完整的约定结构，未将本次结果判定为通过。', {}
    result = {'公文类型': args.get('doc_type', ''), '初审结论': conclusion,
              '待核对要点清单': points, '审阅说明': explanation}
    notices = {'通过': '初审通过：材料要素完整。', '待核对': '材料基本完整，请按清单核实后再提交。',
               '需补充': '材料需补充，请完善缺失或矛盾的内容。', '需人工复核': '初审结果需人工复核，请重新运行或人工处理。'}
    return {'result': json.dumps(result, ensure_ascii=False), 'status': status,
            'key_info': json.dumps(info, ensure_ascii=False), 'check_points': points,
            'conclusion': conclusion, 'notice': notices[status]}
